input.command:
cd /home/vercel-sandbox/buridan-ui; timeout 590 trunk check --all --show-existing --no-progress --output=json > .context/all.json 2>/dev/null; python3 -I - <<'E'
import json,collections
t=open('.context/all.json').read()
try: d=json.loads(t)
except Exception:
    d={'issues':[json.loads(l) for l in t.splitlines() if l.startswith('{')]}
iss=d.get('issues',d)
c=collections.Counter((i['linter'],i.get('code')) for i in iss)
for k,v in c.most_common(40): print(v,k)
E

